text:
{
 "lead": {
  "es": "戦争《せんそう》でなくなった人《ひと》など（戦没者《せんぼつしゃ》等《とう》）の家族《かぞく》（遺族《いぞく》）に、特別《とくべつ》弔慰金《ちょういきん》（なくなった人《ひと》をしのぶ気持《きも》ちをあらわすお金《かね》）をわたすための法律《ほうりつ》です。国《くに》から公務《こうむ》扶助《ふじょ》料《りょう》や遺族年金《いぞくねんきん》などを受《う》けとっている人《ひと》がいない家族《かぞく》が対象《たいしょう》です。",
  "hs": "公務｜扶助《ふじょ》料や遺族年金などを受けている人がいない戦没者《せんぼつしゃ》（戦争で亡くなった人）などの遺族に、特別｜弔慰金《ちょういきん》（とむらいの気持ちをあらわすお金）を支給するための法律です。"
 },
 "facts/0/text": {
  "es": "令和《れいわ》7年《ねん》4月《がつ》1日《ついたち》の時点《じてん》の、戦没者《せんぼつしゃ》等《とう》の家族《かぞく》が対象《たいしょう》です。同《おな》じ戦没者《せんぼつしゃ》等《とう》について、公務《こうむ》扶助《ふじょ》料《りょう》や遺族年金《いぞくねんきん》などを受《う》けとっている人《ひと》がいない家族《かぞく》にわたします。特別《とくべつ》弔慰金《ちょういきん》として、27万《まん》5000円《えん》分《ぶん》の国債《こくさい》（国《くに》が出《だ》す証券《しょうけん》）をわたします。5年《ねん》かけてお金《かね》にかえられます。※正《ただ》しくは「額面《がくめん》27万《まん》5000円《えん》、5年《ねん》償還《しょうかん》の国債《こくさい》」です。",
  "hs": "令和7年4月1日の時点の戦没者《せんぼつしゃ》などの遺族で、同じ戦没者《せんぼつしゃ》などについて公務｜扶助《ふじょ》料や遺族年金などを受けている人がいない人に、特別｜弔慰金《ちょういきん》として額面27万《まん》5000円、5年｜償還《しょうかん》（5年かけてお金が返される）の国債《こくさい》を支給します。"
 },
 "facts/1/text": {
  "es": "特別《とくべつ》弔慰金《ちょういきん》についての決定《けってい》などに、なっとくできないときは、見直《みなお》しをもとめられます（審査請求《しんさせいきゅう》）。そのこたえを出《だ》すときに意見《いけん》を聞《き》く先《さき》を、変《か》えます。今《いま》の「行政不服審査会《ぎょうせいふふくしんさかい》」から、政令《せいれい》（内閣《ないかく》が決《き》めるきまり）で決《き》める審議会《しんぎかい》などに変《か》えます。",
  "hs": "特別｜弔慰金《ちょういきん》についての処分などへの審査請求《しんさせいきゅう》（不服の申し立て）に答える裁決について、意見を聞く先（諮問《しもん》先）を、行政不服｜審査会《しんさかい》から、政令（内閣が決めるきまり）で定める審議会《しんぎかい》などに変えます。"
 },
 "facts/2/text": {
  "es": "令和《れいわ》12年《ねん》4月《がつ》1日《ついたち》の時点《じてん》の、戦没者《せんぼつしゃ》等《とう》の家族《かぞく》にもわたします。同《おな》じ戦没者《せんぼつしゃ》等《とう》について、公務《こうむ》扶助《ふじょ》料《りょう》や遺族年金《いぞくねんきん》などを受《う》けとっている人《ひと》がいない家族《かぞく》です。特別《とくべつ》弔慰金《ちょういきん》として、27万《まん》5000円《えん》分《ぶん》の国債《こくさい》をわたします。5年《ねん》かけてお金《かね》にかえられます。※正《ただ》しくは「額面《がくめん》27万《まん》5000円《えん》、5年《ねん》償還《しょうかん》の国債《こくさい》」です。",
  "hs": "令和12年4月1日の時点の戦没者《せんぼつしゃ》などの遺族で、同じ戦没者《せんぼつしゃ》などについて公務｜扶助《ふじょ》料や遺族年金などを受けている人がいない人にも、特別｜弔慰金《ちょういきん》として額面27万《まん》5000円、5年｜償還《しょうかん》の国債《こくさい》を支給します。"
 },
 "facts/3/text": {
  "es": "この法律《ほうりつ》は、令和《れいわ》7年《ねん》4月《がつ》1日《ついたち》から使《つか》われます。ただし、令和《れいわ》12年《ねん》4月《がつ》1日《ついたち》の時点《じてん》の家族《かぞく》にわたすきまりは、令和《れいわ》12年《ねん》4月《がつ》1日《ついたち》から使《つか》われます。",
  "hs": "この法律は、令和7年4月1日から施行《しこう》されます（使われ始めます）。ただし、令和12年4月1日時点の遺族への支給の規定は、令和12年4月1日から施行《しこう》されます。"
 },
 "more/reason/text": {
  "es": "内閣《ないかく》は、つぎのように説明《せつめい》しています。公務《こうむ》扶助《ふじょ》料《りょう》や遺族年金《いぞくねんきん》などを受《う》けとっている人《ひと》がいない、戦没者《せんぼつしゃ》等《とう》の家族《かぞく》がいます。その家族《かぞく》に、特別《とくべつ》弔慰金《ちょういきん》をわたす必要《ひつよう》があるためです。",
  "hs": "内閣は、公務｜扶助《ふじょ》料や遺族年金などを受けている人がいない戦没者《せんぼつしゃ》などの遺族に、特別｜弔慰金《ちょういきん》を支給する必要があるためとしている。"
 },
 "more/who/text": {
  "es": "令和《れいわ》7年《ねん》4月《がつ》1日《ついたち》と令和《れいわ》12年《ねん》4月《がつ》1日《ついたち》の時点《じてん》の、戦没者《せんぼつしゃ》等《とう》の家族《かぞく》にかかわります。同《おな》じ戦没者《せんぼつしゃ》等《とう》について、公務《こうむ》扶助《ふじょ》料《りょう》や遺族年金《いぞくねんきん》などを受《う》けとっている人《ひと》がいない家族《かぞく》です。",
  "hs": "令和7年4月1日と令和12年4月1日の時点の戦没者《せんぼつしゃ》などの遺族で、同じ戦没者《せんぼつしゃ》などについて公務｜扶助《ふじょ》料や遺族年金などを受けている人がいない人。"
 },
 "more/committee/text": {
  "es": "衆議院《しゅうぎいん》の厚生労働委員会《こうせいろうどういいんかい》では、立憲民主党《りっけんみんしゅとう》・無所属《むしょぞく》が、直《なお》す案《あん》（修正案《しゅうせいあん》）を出《だ》しました。令和《れいわ》12年《ねん》4月《がつ》1日《ついたち》の時点《じてん》の家族《かぞく》に特別《とくべつ》弔慰金《ちょういきん》をわたすきまりを、けずることなどが中身《なかみ》です。修正案《しゅうせいあん》は、賛成《さんせい》が少《すく》なく、通《とお》りませんでした。もとの案《あん》は、全員《ぜんいん》が賛成《さんせい》して通《とお》りました。参議院《さんぎいん》の厚生労働委員会《こうせいろうどういいんかい》では、質問《しつもん》がありました。特別《とくべつ》弔慰金《ちょういきん》のしくみの目的《もくてき》や、わたし方《かた》のあり方《かた》、これからの戦没者《せんぼつしゃ》の家族《かぞく》などをささえる取《と》り組《く》み（援護《えんご》施策《しさく》）などについてです。全員《ぜんいん》が賛成《さんせい》して、もとの案《あん》のまま通《とお》りました。どちらの委員会《いいんかい》でも、委員会《いいんかい》の注文《ちゅうもん》（附帯決議《ふたいけつぎ》）がつけられました。",
  "hs": "衆議院厚生労働委員会では、立憲民主党・無所属が、令和12年4月1日の遺族への特別｜弔慰金《ちょういきん》の支給規定を削除《さくじょ》することなどを内容とする修正案を出したが、賛成少数で否決され、原案は全会一致《ぜんかいいっち》で可決した。参議院厚生労働委員会では、特別｜弔慰金《ちょういきん》制度の趣旨《しゅし》、支給のあり方、今後の援護《えんご》施策《しさく》の取組などについて質疑が行われ、全会一致《ぜんかいいっち》で原案どおり可決した。両院の委員会で附帯決議《ふたいけつぎ》（委員会がつけた注文）がつけられた。"
 },
 "more/views/0/text": {
  "es": "日本共産党《にほんきょうさんとう》は、政府《せいふ》の案《あん》に賛成《さんせい》しました。特別《とくべつ》弔慰金《ちょういきん》のとりくみは、戦没者《せんぼつしゃ》等《とう》の家族《かぞく》が受《う》けた苦労《くろう》を考《かんが》えると、必要《ひつよう》な改正《かいせい》だと述《の》べました。立憲民主党《りっけんみんしゅとう》が出《だ》した修正案《しゅうせいあん》には、反対《はんたい》しました。これからも特別《とくべつ》弔慰金《ちょういきん》がわたされつづけるのかが、はっきりしないとしました。",
  "hs": "日本共産党は、特別｜弔慰金《ちょういきん》の措置《そち》は戦没者《せんぼつしゃ》などの遺族が受けた労苦をふまえると必要な改正だとして、政府案に賛成した。立憲民主党提案の修正案には、今後の特別｜弔慰金《ちょういきん》の支給が維持《いじ》されるのかが明確でないとして反対した。"
 }
}
